insert into hb_record (hb_org_id, hb_org_name, hb_user_id, 
  hb_user_name, product_name, create_time
  )
values (#{hbOrgId,jdbcType=BIGINT}, #{hbOrgName,jdbcType=VARCHAR}, #{hbUserId,jdbcType=BIGINT}, 
  #{hbUserName,jdbcType=VARCHAR}, #{productName,jdbcType=VARCHAR}, #{createTime,jdbcType=TIMESTAMP}
  )

mapper.select:
select

from hb_record


    and hb_org_id = #{hbOrgId,jdbcType=BIGINT}


    and hb_user_name like CONCAT(CONCAT('%',replace(#{hbUserName,jdbcType=VARCHAR},' ','')), '%')


    and product_name = #{productName,jdbcType=VARCHAR}


    and date_format(create_time,'%Y-%m-%d') >= date_format(#{startDate,jdbcType=DATE},'%Y-%m-%d')


    and date_format(create_time,'%Y-%m-%d') <= date_format(#{endDate,jdbcType=DATE},'%Y-%m-%d')


order by id desc
limit #{page}, #{pageSize}

select count(1) from hb_record
and hb_org_id = #{hbOrgId,jdbcType=BIGINT}
and hb_user_name like CONCAT(CONCAT('%',replace(#{hbUserName,jdbcType=VARCHAR},' ','')), '%')
and product_name = #{productName,jdbcType=VARCHAR}
and date_format(create_time,'%Y-%m-%d') >= date_format(#{startDate,jdbcType=DATE},'%Y-%m-%d')
and date_format(create_time,'%Y-%m-%d') <= date_format(#{endDate,jdbcType=DATE},'%Y-%m-%d')
